"""Raccoon Golf's art, generated by tools/generate_golf_assets.py.

All art is original and procedural. The manifest carries the numbers that
belong to the art (focal length the sky was painted for, tree anchors, where
Lenny's arms attach, the ground's colours) so they travel with the sprites.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path

import cv2
import numpy as np

ASSET_DIR = Path(__file__).resolve().parents[4] / "assets" / "golf" / "generated"
MANIFEST = ASSET_DIR / "manifest.json"
GENERATOR = "uv run python tools/generate_golf_assets.py"


class AssetsMissingError(RuntimeError):
    pass


@dataclass
class GolfArt:
    sky: np.ndarray  # BGR panorama, one full turn of yaw, PANO_W x PANO_H (horizon at the bottom row)
    sea: np.ndarray  # BGR, 1280 wide, tiles horizontally; row 0 is the horizon
    haze: np.ndarray  # BGRA strip blended under the horizon
    trees: dict[str, np.ndarray]  # kind -> BGRA, anchored at manifest foot
    lenny: np.ndarray  # BGRA body at address, no arms
    ball: np.ndarray  # BGRA
    gauge: np.ndarray  # BGRA frame
    gauge_fill: np.ndarray  # BGRA fill, revealed from the bottom
    manifest: dict = field(default_factory=dict)


_cache: GolfArt | None = None


def _read(name: str, flags: int = cv2.IMREAD_UNCHANGED) -> np.ndarray:
    path = ASSET_DIR / name
    if not path.exists():
        raise AssetsMissingError(f"missing {path.name}. Run: {GENERATOR}")
    img = cv2.imread(str(path), flags)
    if img is None:
        raise AssetsMissingError(f"could not decode {path}")
    return img


def load_art(*, reload: bool = False) -> GolfArt:
    global _cache
    if _cache is not None and not reload:
        return _cache
    if not MANIFEST.exists():
        raise AssetsMissingError(f"missing {MANIFEST}. Run: {GENERATOR}")
    spec = json.loads(MANIFEST.read_text())
    sky = _read("sky.png", cv2.IMREAD_COLOR)
    # Stored at half resolution (it is soft and dithered; full size is 4x the file).
    sky = cv2.resize(sky, (int(spec["pano_w"]), int(spec["pano_h"])), interpolation=cv2.INTER_LINEAR)
    _cache = GolfArt(
        sky=sky,
        sea=_read("sea.png", cv2.IMREAD_COLOR),
        haze=_read("haze.png"),
        trees={k: _read(v["file"]) for k, v in spec["trees"].items()},
        lenny=_read(spec["lenny"]["file"]),
        ball=_read("ball.png"),
        gauge=_read("gauge.png"),
        gauge_fill=_read("gauge_fill.png"),
        manifest=spec,
    )
    return _cache


def stub_art() -> GolfArt:
    """Tiny flat art with the real manifest's shape, for tests that never look."""
    spec = {
        "focal": 1000.0, "pano_w": 6283, "pano_h": 440, "sun": [0.12, 330],
        "trees": {"palm": {"foot": [8, 30], "top": 0}, "round": {"foot": [8, 30], "top": 0}},
        "lenny": {"shoulder_back": [10, 12], "shoulder_front": [14, 12], "arm": 8.0, "club": 12.0,
                  "address_dir": 34.0,
                  "colours": {k: [200, 200, 200] for k in ("fur", "sleeve", "glove", "ink", "shaft", "head", "face")}},
        "gauge": {"inner": [2, 2, 14, 98], "full_frac": 1 / 1.15},
        "ground": {k: [100, 160, 90] for k in ("rough", "fairway", "fairway_stripe", "green", "green_stripe",
                                               "fringe", "tee", "bunker", "bunker_rim", "water", "water_hi",
                                               "water_rim", "beach", "edge", "haze", "sea")},
        "ball_visual_radius_m": 0.075,
    }
    rgba = lambda w, h: np.full((h, w, 4), 200, np.uint8)  # noqa: E731
    return GolfArt(
        sky=np.full((440, 6283, 3), (230, 200, 120), np.uint8),
        sea=np.full((560, 1280, 3), (200, 140, 30), np.uint8),
        haze=np.zeros((64, 1280, 4), np.uint8),
        trees={"palm": rgba(16, 32), "round": rgba(16, 32)},
        lenny=rgba(24, 30),
        ball=rgba(8, 8),
        gauge=rgba(16, 100),
        gauge_fill=rgba(16, 100),
        manifest=spec,
    )
